Rel(HTTPS_WebSocket_Handler, Routing_Security_Proxy, "Passes authenticated requests")

@enduml

Data Localization Router.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Data Localization Router container

Container_Boundary(data_localization_router, "Data Localization Router") {
    Component(Geo_DNS_Router, "Geo-DNS Router", "Geo-DNS and TLS SNI Parsing", "Routes incoming patient and clinician requests to the appropriate regional infrastructure based on geographic origin.")
    Component(Stateless_Interceptor_Middleware, "Stateless Interceptor Middleware", "Stateless Middleware", "Intercepts requests at the edge to enforce fail-closed security and data residency policies.")
    Component(Data_Residency_Enforcer, "Data Residency Enforcer", "Policy Routing Engine", "Ensures data persistence is strictly directed to GCP-managed regional databases ineurope-west3 and us-central1.")
}

Rel(Geo_DNS_Router, Stateless_Interceptor_Middleware, "Passes parsed requests for security and policy inspection")
Rel(Stateless_Interceptor_Middleware, Data_Residency_Enforcer, "Enforces routing rules to regional databases and external services")

@enduml

Anti-Corruption Layer (ACL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(acl, "Anti-Corruption Layer (ACL)") {
    Component(Pluggable_Regional_Adapter, "Pluggable Regional Adapter", "Pluggable Regional Modules", "Manages diverging EU (National Standards) and US (HL7 FHIR) formats.")
    Component(Fault_Tolerance_Handler, "Fault Tolerance Handler", "Circuit Breaker & Idempotency Keys", "Prevents cascading failures and duplicate pharmacy submissions over unstable links.")
    Component(Observability_Agent, "Observability Agent", "Distributed Tracing & Correlation IDs", "Ensures end-to-end observability across regional boundaries.")
}

Rel(Pluggable_Regional_Adapter, Fault_Tolerance_Handler, "Routes requests through")
Rel(Fault_Tolerance_Handler, Observability_Agent, "Tracks transactions via")

@enduml

Cryptographic Vault.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(cryptographic_vault, "Cryptographic Vault") {
    Component(Key_Management_Interface, "Key Management Interface", "Provider-Agnostic Key Management Interface (Wrapper Pattern)", "Interfaces with GCP Cloud KMS and HSM using a wrapper pattern for provider-agnostic key management.")
    Component(Envelope_Encryption_Service, "Envelope Encryption Service", "Python / Cryptographic Libraries", "Handles requests for Data Encryption Keys (DEKs) using envelope encryption principles.")
    Component(Vault_gRPC_Handler, "Vault gRPC Handler", "gRPC with Protocol Buffers", "Provides low-latency, type-safe API communication for calling microservices interacting with the vault.")
}

System_Ext(Cryptographic_Vault_Container_GCP_Cloud_KMS_HSM, "Cryptographic Vault Container (GCP Cloud KMS / HSM)", "GCP Cloud KMS / Hardware Security Module")

Rel(Vault_gRPC_Handler, Key_Management_Interface, "Uses to interact with hardware-backed key isolation", "gRPC")
Rel(Vault_gRPC_Handler, Envelope_Encryption_Service, "Requests Data Encryption Keys (DEKs)", "gRPC")
Rel(Key_Management_Interface, Cryptographic_Vault_Container_GCP_Cloud_KMS_HSM, "Interacts with hardware security modules", "HTTPS/API")

@enduml

